import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";

export type DigitalWallet1 = {
  /** Identifies the digital wallet provider to the payer. */
  provider?: string;
  /**
   * The consent ID returned by provider. Merchant will use this reference to launch the KONEK UI.
   */
  reference?: string;
  /**
   * The unique identifier generated by proider to trace the consent delivery process. Merchant will
   * use this reference to launch the KONEK UI.
   */
  providerReference?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const digitalWallet1Properties: s.Shape<DigitalWallet1> = {
  provider: s.optional(s.string()),
  reference: s.optional(s.string()),
  providerReference: s.optional(s.string()),
  _keysMap: {
    providerReference: "provider_reference",
  },
};

export const digitalWallet1InternalSchema: Schema<DigitalWallet1> = s.object<DigitalWallet1>(
  digitalWallet1Properties,
  { additionalProperties: s.json() },
);

export const digitalWallet1Schema: Schema<DigitalWallet1> = s.lazySchema(() =>
  s.object<DigitalWallet1>(
    {
      ...digitalWallet1Properties,
      provider: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
    },
    { additionalProperties: s.json() },
  ),
);
